item.command:
/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic       sel,
    input  logic [7:0] a,
    input  logic [7:0] b,
    output logic [7:0] out
);
    assign out = sel ? b : a;
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'EOF'
"'`timescale 1ns/1ps
module dev_tb;
    logic sel;
    logic [7:0] a, b;
    wire [7:0] out;
    integer ai, bi, si;
    integer checks = 0;
    TopModule dut (.sel(sel), .a(a), .b(b), .out(out));
    initial begin
        for (si = 0; si < 2; si = si + 1) begin
            for (ai = 0; ai < 256; ai = ai + 1) begin
                for (bi = 0; bi < 256; bi = bi + 1) begin
                    sel = si[0]; a = ai[7:0]; b = bi[7:0];
                    #1;
                    if (out !== (si == 0 ? a : b))
                        $fatal(1, "FAIL sel=%b a=%h b=%h out=%h", sel, a, b, out);
                    checks = checks + 1;
                end
            end
        end
        $display("PASS: %0d exhaustive binary input checks", checks);
        $finish;
    end
    initial begin
        #200000;
        $fatal(1, "FAIL: simulation timeout");
    end
endmodule
EOF
timeout 30s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > compile.log 2>&1
compile_status=$?
cat compile.log
if [ "$compile_status" -eq 0 ]; then
    timeout 30s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim > simulation.log 2>&1
    simulation_status=$?
    cat simulation.log
else
    simulation_status=not_run
fi
printf '"'compile_exit=%s\\nsimulation_exit=%s\\n' \""'$compile_status" "$simulation_status" > development_status.log'

